<?php
$handle = mysqli_init();
mysqli_real_connect($handle, 'localhost', 'user', 'pass', null, 3306, null, 0);
mysqli_query($handle, "INSERT INTO wp_options (option_name, option_value, autoload) VALUES ('siteurl', 'https://example.test', 'yes')");
$direct = mysqli_query($handle, "SELECT option_name FROM wp_options WHERE option_name = 'siteurl' LIMIT 1");
$direct_row = mysqli_fetch_assoc($direct);
echo $direct_row['option_name'];
echo '|';
$missing = mysqli_query($handle, "SELECT option_name FROM wp_options WHERE option_name = 'missing' LIMIT 1");
echo mysqli_num_rows($missing);
echo '|';
$stmt = mysqli_prepare($handle, 'SELECT option_name FROM wp_options WHERE option_name = ? LIMIT 1');
$name = 'siteurl';
mysqli_stmt_bind_param($stmt, 's', $name);
mysqli_stmt_execute($stmt);
$prepared = mysqli_stmt_get_result($stmt);
$prepared_row = mysqli_fetch_assoc($prepared);
echo $prepared_row['option_name'];
echo '|';
$name = 'missing';
mysqli_stmt_execute($stmt);
$prepared_missing = mysqli_stmt_get_result($stmt);
echo mysqli_num_rows($prepared_missing);
echo '|';
$execute_query = mysqli_execute_query($handle, 'SELECT `option_name` FROM `wp_options` WHERE `option_name` = ? LIMIT 1', array('siteurl'));
$execute_query_row = mysqli_fetch_assoc($execute_query);
echo $execute_query_row['option_name'];
